'use strict';

// Task 213 — canonical integration state: Node mirror parity + validator.
//
// The golden fixture (revIntegrationState.golden.json) is generated by
// python/scripts/gen_integration_state_golden.py from the AUTHORITATIVE
// Python evaluator (python/src/intelligence/integration_state.py). This test
// feeds the same records into the Node keystone and deep-compares the
// results: two implementations, one contract (REV-DEC-0013). Regenerate the
// golden only after a deliberate, documented state-machine change.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');

process.env.SHOPIFY_TOKEN_ENCRYPTION_KEY = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef';
const DB_PATH = require.resolve('../../configs/database');
require.cache[DB_PATH] = { id: DB_PATH, filename: DB_PATH, loaded: true, exports: { prisma: null } };

const {
  INTEGRATION_STATE_CONTRACT_VERSION,
  OVERALL_STATES,
  SYNC_PHASES,
  APP_REQUESTED_SCOPES,
  evaluateIntegrationState,
  normalizeStoreRecord,
  worstState,
  canonicalStateSummary,
  validateIntegrationState,
} = require('../revIntegrationState');

const GOLDEN = JSON.parse(fs.readFileSync(path.join(__dirname, 'revIntegrationState.golden.json'), 'utf8'));
const NOW = new Date(GOLDEN.now);

test('contract constants are the closed sets', () => {
  assert.equal(GOLDEN.contract_version, INTEGRATION_STATE_CONTRACT_VERSION);
  assert.equal(INTEGRATION_STATE_CONTRACT_VERSION, 'rev-integration-state-v1');
  assert.deepEqual([...OVERALL_STATES].sort(), [
    'authorization_expired', 'authorization_required', 'authorization_revoked',
    'connected', 'disconnected', 'limited_access', 'needs_attention',
    'sync_failed', 'sync_partial', 'synchronizing', 'unknown', 'unsupported',
  ]);
  assert.equal(OVERALL_STATES.length, 12);
  assert.ok(SYNC_PHASES.includes('running') && SYNC_PHASES.includes('stalled'));
});

for (const c of GOLDEN.cases) {
  test(`mirror parity: ${c.name} -> ${c.expected.overall_status} (${c.expected.status_reason})`, () => {
    const actual = evaluateIntegrationState(c.records, NOW);
    assert.deepEqual(actual, c.expected);
    // The token that was in the input records must never appear.
    const blob = JSON.stringify(actual);
    assert.ok(!blob.includes('shpat_GOLDEN_SECRET_NEVER_IN_OUTPUT'));
    const validation = validateIntegrationState(actual);
    assert.equal(validation.valid, true, validation.problems.join('; '));
    // Task 213 — compact summary field-parity with the Python keystone.
    assert.deepEqual(canonicalStateSummary(actual), c.expected_summary);
  });
}

for (const c of GOLDEN.rollup_cases) {
  test(`rollup: [${c.states.join(', ')}] -> ${c.expected}`, () => {
    assert.equal(worstState(c.states), c.expected);
  });
}

test('app-requested scopes are pinned to the build source (utils/shopify.js)', () => {
  const js = fs.readFileSync(path.join(__dirname, '../../utils/shopify.js'), 'utf8');
  const start = js.indexOf('const scope = [...new Set([');
  const end = js.indexOf("].join(',');");
  assert.ok(start > -1 && end > start, 'hard-coded scope block found in utils/shopify.js');
  const block = js.slice(start, end);
  const hardcoded = [...block.matchAll(/'(read_[a-z_]+)'/g)].map(m => m[1]);
  assert.deepEqual([...new Set(hardcoded)].sort(), [...APP_REQUESTED_SCOPES].sort());
});

test('normalizeStoreRecord never carries the token into the evaluator input', () => {
  const normalized = normalizeStoreRecord({
    id: 's1', organization_id: 'o1', platform: 'shopify', shop_domain: 't.myshopify.com',
    status: 'active', access_token: 'shpat_absolutely_secret',
    granted_scopes: 'read_products,read_orders',
    installed_at: '2026-10-01T00:00:00Z', last_synced_at: '2026-11-07T11:00:00Z',
    updated_at: '2026-11-07T11:55:00Z',
  }, 'o1');
  assert.equal(normalized.has_token, true);
  assert.equal('access_token' in normalized, false);
  assert.deepEqual(normalized.granted_scopes, ['read_products', 'read_orders']);
  assert.equal(normalized.scope_list_recorded, true);
});

test('validator: fail-closed on unknown states and tampered blocks', () => {
  const good = evaluateIntegrationState(GOLDEN.cases[0].records, NOW);
  assert.equal(validateIntegrationState(good).valid, true);

  const unknownState = structuredClone(good);
  unknownState.overall_status = 'operational';
  let v = validateIntegrationState(unknownState);
  assert.equal(v.valid, false);
  assert.ok(v.problems.some(p => p.includes('overall_status')));

  const tamperedAuth = structuredClone(good);
  tamperedAuth.authorization.verification = 'certified_by_magic';
  v = validateIntegrationState(tamperedAuth);
  assert.equal(v.valid, false);
  assert.ok(v.problems.some(p => p.includes('authorization.verification')));

  const missingBlock = structuredClone(good);
  delete missingBlock.synchronization;
  v = validateIntegrationState(missingBlock);
  assert.equal(v.valid, false);
  assert.ok(v.problems.some(p => p.includes('synchronization')));

  const wrongVersion = structuredClone(good);
  wrongVersion.contract_version = 'rev-integration-state-v99';
  v = validateIntegrationState(wrongVersion);
  assert.equal(v.valid, false);
  assert.ok(v.problems.some(p => p.includes('contract_version')));

  const badPhase = structuredClone(good);
  badPhase.synchronization.state = 'flying';
  v = validateIntegrationState(badPhase);
  assert.equal(v.valid, false);
  assert.ok(v.problems.some(p => p.includes('synchronization.state')));
});

test('validator: secret material is rejected at the boundary', () => {
  const good = evaluateIntegrationState(GOLDEN.cases[0].records, NOW);
  good.authorization.granted_scopes.push('shpat_leaked_credential');
  const v = validateIntegrationState(good);
  assert.equal(v.valid, false);
  assert.ok(v.problems.some(p => p.includes('credential material')));
});

test('determinism: same records and now produce the same contract', () => {
  const records = GOLDEN.cases[0].records;
  assert.deepEqual(evaluateIntegrationState(records, NOW), evaluateIntegrationState(records, NOW));
});

test('no record evaluates to disconnected without throwing', () => {
  const r = evaluateIntegrationState({}, NOW);
  assert.equal(r.overall_status, 'disconnected');
  assert.equal(r.status_reason, 'no_installation_record');
  assert.equal(validateIntegrationState(r).valid, true);
});
